referenceSolutions.javascript:
export function solve(maximum, calls) {
  return calls.map((args, i) => (i < maximum ? args.reduce((a, b) => a + b, 0) : null));
}

referenceSolutions.typescript:
type Value = any;
export function solve(maximum: Value, calls: Value): Value {
  return calls.map((args: Value, i: Value) =>
    i < maximum ? args.reduce((a: Value, b: Value) => a + b, 0) : null,
  );
}
